/**
 * API key store.
 *
 * Hook authentication layer. Users generate keys via the dashboard; the
 * plaintext is shown once, hashed with SHA-256, and stored against their
 * OIDC sub. Every subsequent hook request carries the plaintext in an
 * `Authorization: Bearer jaid_live_...` header; the server hashes and
 * looks up.
 *
 * Key format: `jaid_live_` + 43 base62 chars (256 bits of entropy).
 *
 * Three implementations, same interface:
 *   - `InMemoryApiKeyStore` — process-local Map, for local dev.
 *   - `DynamoApiKeyStore`   — against `jaid-api-keys` in eu-west-1.
 *   - `CachedApiKeyStore`   — write-through LRU wrapper; 5m positive /
 *                             30s negative, so revokes propagate fast.
 *
 * Injection-resistance invariants (see `DynamoApiKeyStore`):
 *   - No PartiQL; all values bound via placeholders.
 *   - Key attributes are derived server-side from hashed plaintext;
 *     no user input ever reaches a partition key or sort key.
 *   - The GSI1 keys are set / unset explicitly; never from user input.
 */

import { createHash, randomBytes, timingSafeEqual } from "node:crypto";

// ---- types -----------------------------------------------------------------

export type KeyType = "user" | "service" | "benchmark";

/** What we persist for each key. The plaintext is NEVER stored. */
export interface KeyRecord {
  /** sha256(plaintext) as hex, 64 chars. Primary identifier. */
  hashedKey: string;
  /** First 10 chars + last 4 chars of the plaintext, masked middle.
   *  Display-only; safe to return from `listByOwner`. */
  keyPreview: string;
  /** OIDC `sub` claim — the stable owner identifier. */
  ownerSub: string;
  /** OIDC `email` claim — display convenience on the dashboard. */
  ownerEmail: string | null;
  /** User-supplied label, e.g. "MacBook laptop hook". */
  description: string;
  keyType: KeyType;
  createdAt: string;
  /** Updated async on every successful validation. */
  lastUsedAt: string | null;
  /** Set when revoked; absent for active keys. */
  revokedAt: string | null;
  /** Who pressed the revoke button (their OIDC sub). */
  revokedBy: string | null;
}

/** Shape returned to the hook caller immediately after generation.
 *  Includes the plaintext ONCE — the user must copy it now or never. */
export interface GeneratedKey extends KeyRecord {
  plaintext: string;
}

/** Input for key generation. */
export interface GenerateKeyInput {
  ownerSub: string;
  ownerEmail: string | null;
  description: string;
  keyType?: KeyType;
}

/** Result of a successful validation — used to attach identity to a request. */
export interface ValidatedKey {
  hashedKey: string;
  ownerSub: string;
  ownerEmail: string | null;
  keyType: KeyType;
}

export interface ApiKeyStore {
  /** Mint a new key, persist the hash, return the plaintext + metadata. */
  generateKey(input: GenerateKeyInput): Promise<GeneratedKey>;

  /** Validate a plaintext key. Returns identity on success, null otherwise.
   *  Updates `lastUsedAt` as a side effect (best-effort, not awaited by callers). */
  validateKey(plaintext: string): Promise<ValidatedKey | null>;

  /** List a user's active keys, newest first. Does not return revoked keys. */
  listByOwner(ownerSub: string, limit?: number): Promise<KeyRecord[]>;

  /** Admin-only: list every active key across all owners. Implementations
   *  may cap or paginate. Returns at most `limit` records, newest first
   *  where the implementation can sort cheaply (Dynamo cannot without a
   *  GSI, so the order is undefined for the Dynamo-backed store). */
  listAll(limit?: number): Promise<KeyRecord[]>;

  /** Soft-revoke a key by hash. `revokedBy` is the OIDC sub of the caller. */
  revokeKey(hashedKey: string, revokedBy: string): Promise<boolean>;

  /** Load a single key by hash, including revoked. Null if unknown.
   *  Primarily used by `CachedApiKeyStore` and forensics; regular auth
   *  should go through `validateKey`. */
  loadKey(hashedKey: string): Promise<KeyRecord | null>;
}

// ---- key minting -----------------------------------------------------------

const BASE62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
/** 43 base62 chars ≈ 43 × log₂(62) ≈ 256 bits of entropy. */
const KEY_BODY_LENGTH = 43;
const KEY_PREFIX = "jaid_live_";

/**
 * Generate a new plaintext key. Uses `crypto.randomBytes` for entropy and
 * maps bytes to base62 via rejection sampling so the distribution is uniform
 * (naive modulo yields slightly non-uniform output — cheap to avoid).
 */
export function mintPlaintext(): string {
  const out: string[] = [];
  while (out.length < KEY_BODY_LENGTH) {
    // Pull a chunk of bytes; reject any >= 248 so that bytes % 62 is uniform
    // over 0..61 (248 = 4 × 62, the largest multiple that fits in a byte).
    const chunk = randomBytes(KEY_BODY_LENGTH * 2);
    for (const b of chunk) {
      if (b >= 248) continue;
      out.push(BASE62[b % 62]);
      if (out.length === KEY_BODY_LENGTH) break;
    }
  }
  return KEY_PREFIX + out.join("");
}

/** sha256(plaintext), hex-encoded. Used for the primary key in Dynamo. */
export function hashKey(plaintext: string): string {
  return createHash("sha256").update(plaintext, "utf8").digest("hex");
}

/** Masked preview for display: first 10 + last 4 chars, middle replaced
 *  with ellipsis. Safe to show in the dashboard list. */
export function keyPreview(plaintext: string): string {
  if (plaintext.length <= 14) return plaintext; // pathologically short — just show it
  return `${plaintext.slice(0, 14)}...${plaintext.slice(-4)}`;
}

/** Validate the surface shape of a key. Bearer tokens that don't match this
 *  shape get rejected without touching Dynamo. */
export function looksLikeJaidKey(s: unknown): s is string {
  if (typeof s !== "string") return false;
  if (!s.startsWith(KEY_PREFIX)) return false;
  const body = s.slice(KEY_PREFIX.length);
  if (body.length !== KEY_BODY_LENGTH) return false;
  // Base62 character class.
  return /^[0-9A-Za-z]+$/.test(body);
}

// ---- in-memory impl --------------------------------------------------------

/**
 * Process-local key store. Used for local dev parity with the Dynamo
 * implementation. All state lives in a Map keyed by hash; data is lost on
 * restart. Never use in production.
 */
export class InMemoryApiKeyStore implements ApiKeyStore {
  private keys = new Map<string, KeyRecord>();

  async generateKey(input: GenerateKeyInput): Promise<GeneratedKey> {
    const plaintext = mintPlaintext();
    const hashedKey = hashKey(plaintext);
    const record: KeyRecord = {
      hashedKey,
      keyPreview: keyPreview(plaintext),
      ownerSub: input.ownerSub,
      ownerEmail: input.ownerEmail,
      description: input.description,
      keyType: input.keyType ?? "user",
      createdAt: new Date().toISOString(),
      lastUsedAt: null,
      revokedAt: null,
      revokedBy: null,
    };
    this.keys.set(hashedKey, record);
    return { ...record, plaintext };
  }

  async validateKey(plaintext: string): Promise<ValidatedKey | null> {
    if (!looksLikeJaidKey(plaintext)) return null;
    const hashedKey = hashKey(plaintext);
    const record = this.keys.get(hashedKey);
    if (!record || record.revokedAt) return null;
    // Constant-time check against the stored hash as defence-in-depth;
    // the Map lookup already used strict equality, but we want any future
    // move to a different lookup primitive to remain timing-safe.
    const a = Buffer.from(hashedKey, "hex");
    const b = Buffer.from(record.hashedKey, "hex");
    if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
    // Side effect: bump lastUsedAt. Fire-and-forget-ish; the await is free
    // in-memory and we don't want a stale field if the caller never checks.
    record.lastUsedAt = new Date().toISOString();
    return {
      hashedKey: record.hashedKey,
      ownerSub: record.ownerSub,
      ownerEmail: record.ownerEmail,
      keyType: record.keyType,
    };
  }

  async listByOwner(ownerSub: string, limit = 50): Promise<KeyRecord[]> {
    const active: KeyRecord[] = [];
    for (const r of this.keys.values()) {
      if (r.ownerSub === ownerSub && !r.revokedAt) active.push(r);
    }
    active.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    return active.slice(0, limit);
  }

  async listAll(limit = 200): Promise<KeyRecord[]> {
    const active: KeyRecord[] = [];
    for (const r of this.keys.values()) {
      if (!r.revokedAt) active.push(r);
    }
    active.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    return active.slice(0, limit);
  }

  async revokeKey(hashedKey: string, revokedBy: string): Promise<boolean> {
    const record = this.keys.get(hashedKey);
    if (!record || record.revokedAt) return false;
    record.revokedAt = new Date().toISOString();
    record.revokedBy = revokedBy;
    return true;
  }

  async loadKey(hashedKey: string): Promise<KeyRecord | null> {
    return this.keys.get(hashedKey) ?? null;
  }
}

/**
 * DynamoDB-backed ApiKeyStore.
 *
 * Source-of-truth persistence for API key metadata. Designed to sit behind
 * `CachedApiKeyStore` — this class issues a GetItem for every validation,
 * so running it un-cached would add a Dynamo round-trip to every single
 * hook call. The cache is what keeps the hot path fast.
 *
 * Item shape (single table `jaid-api-keys`):
 *
 *   pk          = APIKEY#<sha256-hex>
 *   sk          = META
 *   hashedKey   = <sha256-hex>           — duplicated from pk for clarity
 *   keyPreview  = "jaid_live_Abcd...wxyz"
 *   ownerSub    = OIDC sub claim         — STABLE owner identifier
 *   ownerEmail  = OIDC email claim       — display convenience
 *   description = "user-supplied label"
 *   keyType     = "user" | "service" | "benchmark"
 *   createdAt   = ISO-8601
 *   lastUsedAt  = ISO-8601 or null
 *   revokedAt?  = ISO-8601               — absent means active
 *   revokedBy?  = OIDC sub               — absent means active
 *   gsi1pk      = "USER#<ownerSub>"      — SET on active keys, REMOVED on revoke
 *   gsi1sk      = "APIKEY#<createdAt>"   — SET on active keys, REMOVED on revoke
 *   ttl?        = <epoch-seconds>        — SET on revoke, 90d out
 *
 * GSI1 is only present on active keys, so `listByOwner` Query returns active
 * keys only, no filter expression needed. Revoked keys stay in the table
 * (for forensics) until their TTL lapses.
 *
 * Injection-resistance invariants (DO NOT BREAK):
 *   - No PartiQL. All DynamoDB operations use the parameterised
 *     DocumentClient commands — values are bound via ExpressionAttributeValues,
 *     never string-concatenated.
 *   - Partition / sort keys are derived server-side from `hashKey(plaintext)`
 *     and fixed literals. User-supplied fields (description, ownerSub,
 *     ownerEmail) land in values only, never in key positions or expression
 *     strings.
 *   - UpdateExpression attribute names are authored in code via
 *     ExpressionAttributeNames; only the VALUES come from runtime state.
 */

import { DynamoDBClient } from "@aws-sdk/client-dynamodb";
import {
  DynamoDBDocumentClient,
  GetCommand,
  PutCommand,
  UpdateCommand,
  QueryCommand,
  ScanCommand,
} from "@aws-sdk/lib-dynamodb";

import {
  type ApiKeyStore,
  type GenerateKeyInput,
  type GeneratedKey,
  type KeyRecord,
  type ValidatedKey,
  hashKey,
  keyPreview,
  looksLikeJaidKey,
  mintPlaintext,
} from "./api-key-store.js";

export interface DynamoApiKeyStoreOptions {
  tableName: string;
  region: string;
  /** Override for tests. */
  client?: DynamoDBDocumentClient;
  /** TTL in seconds for revoked keys; default 90 days. */
  revokedTtlSeconds?: number;
}

const REVOKED_TTL_DEFAULT = 90 * 24 * 60 * 60;
const GSI_NAME = "gsi1";

function pk(hash: string): string {
  return `APIKEY#${hash}`;
}

function userPk(sub: string): string {
  return `USER#${sub}`;
}

function createdAtSk(createdAt: string): string {
  return `APIKEY#${createdAt}`;
}

function nowEpochSec(): number {
  return Math.floor(Date.now() / 1000);
}

function itemToRecord(item: Record<string, any>): KeyRecord {
  return {
    hashedKey: item.hashedKey,
    keyPreview: item.keyPreview,
    ownerSub: item.ownerSub,
    ownerEmail: item.ownerEmail ?? null,
    description: item.description ?? "",
    keyType: item.keyType ?? "user",
    createdAt: item.createdAt,
    lastUsedAt: item.lastUsedAt ?? null,
    revokedAt: item.revokedAt ?? null,
    revokedBy: item.revokedBy ?? null,
  };
}

export class DynamoApiKeyStore implements ApiKeyStore {
  private readonly tableName: string;
  private readonly client: DynamoDBDocumentClient;
  private readonly revokedTtlSeconds: number;

  constructor(opts: DynamoApiKeyStoreOptions) {
    this.tableName = opts.tableName;
    this.revokedTtlSeconds = opts.revokedTtlSeconds ?? REVOKED_TTL_DEFAULT;
    this.client =
      opts.client ??
      DynamoDBDocumentClient.from(new DynamoDBClient({ region: opts.region }), {
        marshallOptions: {
          removeUndefinedValues: true,
          convertClassInstanceToMap: false,
        },
      });
  }

  async generateKey(input: GenerateKeyInput): Promise<GeneratedKey> {
    const plaintext = mintPlaintext();
    const hashedKey = hashKey(plaintext);
    const createdAt = new Date().toISOString();
    const keyType = input.keyType ?? "user";

    // ConditionExpression guards against the astronomically-unlikely case
    // where two `mintPlaintext()` calls collide — in which case the second
    // caller bubbles a retryable error. Also guards against a key being
    // "re-generated" over an existing record in any future bug.
    await this.client.send(
      new PutCommand({
        TableName: this.tableName,
        Item: {
          pk: pk(hashedKey),
          sk: "META",
          hashedKey,
          keyPreview: keyPreview(plaintext),
          ownerSub: input.ownerSub,
          ownerEmail: input.ownerEmail,
          description: input.description,
          keyType,
          createdAt,
          lastUsedAt: null,
          gsi1pk: userPk(input.ownerSub),
          gsi1sk: createdAtSk(createdAt),
        },
        ConditionExpression: "attribute_not_exists(pk)",
      }),
    );

    return {
      plaintext,
      hashedKey,
      keyPreview: keyPreview(plaintext),
      ownerSub: input.ownerSub,
      ownerEmail: input.ownerEmail,
      description: input.description,
      keyType,
      createdAt,
      lastUsedAt: null,
      revokedAt: null,
      revokedBy: null,
    };
  }

  async validateKey(plaintext: string): Promise<ValidatedKey | null> {
    if (!looksLikeJaidKey(plaintext)) return null;
    const hashedKey = hashKey(plaintext);
    const r = await this.client.send(
      new GetCommand({
        TableName: this.tableName,
        Key: { pk: pk(hashedKey), sk: "META" },
      }),
    );
    if (!r.Item || r.Item.revokedAt) return null;

    // Best-effort lastUsedAt bump. We don't await or throw on error — a
    // validation should not fail because the stat update failed. Not
    // wrapped in try/await so it does not leak a rejection on the next
    // tick; we attach a swallow-handler.
    this.client
      .send(
        new UpdateCommand({
          TableName: this.tableName,
          Key: { pk: pk(hashedKey), sk: "META" },
          UpdateExpression: "SET lastUsedAt = :t",
          ExpressionAttributeValues: { ":t": new Date().toISOString() },
        }),
      )
      .catch(() => {
        /* swallow — telemetry bump, not correctness-critical */
      });

    return {
      hashedKey: r.Item.hashedKey,
      ownerSub: r.Item.ownerSub,
      ownerEmail: r.Item.ownerEmail ?? null,
      keyType: r.Item.keyType ?? "user",
    };
  }

  async listByOwner(ownerSub: string, limit = 50): Promise<KeyRecord[]> {
    // GSI1 holds active keys only (revoked ones have gsi1pk/sk removed on
    // revoke), so Query against USER#<sub> returns exactly the user's
    // active keys without a FilterExpression.
    const r = await this.client.send(
      new QueryCommand({
        TableName: this.tableName,
        IndexName: GSI_NAME,
        KeyConditionExpression: "gsi1pk = :pk",
        ExpressionAttributeValues: { ":pk": userPk(ownerSub) },
        ScanIndexForward: false, // newest first
        Limit: limit,
      }),
    );
    return (r.Items ?? []).map(itemToRecord);
  }

  async listAll(limit = 200): Promise<KeyRecord[]> {
    // No GSI on "all keys" — Scan is the right primitive here. We
    // FilterExpression on "active only" so revoked keys (which keep
    // their pk/sk but get a revokedAt) drop out at the DDB layer
    // rather than wasting bytes over the wire. For a table with
    // <10k items this is fine; if it ever grew we'd add a GSI.
    const items: Record<string, any>[] = [];
    let cursor: Record<string, any> | undefined;
    do {
      const r = await this.client.send(
        new ScanCommand({
          TableName: this.tableName,
          FilterExpression: "attribute_not_exists(revokedAt) AND sk = :meta",
          ExpressionAttributeValues: { ":meta": "META" },
          Limit: 100,
          ExclusiveStartKey: cursor,
        }),
      );
      if (r.Items) items.push(...r.Items);
      cursor = r.LastEvaluatedKey;
      if (items.length >= limit) break;
    } while (cursor);
    items.sort((a, b) => String(b.createdAt ?? "").localeCompare(String(a.createdAt ?? "")));
    return items.slice(0, limit).map(itemToRecord);
  }

  async revokeKey(hashedKey: string, revokedBy: string): Promise<boolean> {
    const revokedAt = new Date().toISOString();
    const ttl = nowEpochSec() + this.revokedTtlSeconds;

    // Atomic soft-delete:
    //   - SET revokedAt, revokedBy, ttl
    //   - REMOVE gsi1pk, gsi1sk so the key drops off listByOwner immediately
    //   - Condition: exists and not already revoked
    try {
      await this.client.send(
        new UpdateCommand({
          TableName: this.tableName,
          Key: { pk: pk(hashedKey), sk: "META" },
          UpdateExpression:
            "SET revokedAt = :ra, revokedBy = :rb, #ttl = :ttl REMOVE gsi1pk, gsi1sk",
          ConditionExpression:
            "attribute_exists(pk) AND attribute_not_exists(revokedAt)",
          ExpressionAttributeNames: { "#ttl": "ttl" },
          ExpressionAttributeValues: {
            ":ra": revokedAt,
            ":rb": revokedBy,
            ":ttl": ttl,
          },
        }),
      );
      return true;
    } catch (err: any) {
      // Condition failure = already revoked or missing. Return false;
      // any other error propagates.
      if (err?.name === "ConditionalCheckFailedException") return false;
      throw err;
    }
  }

  async loadKey(hashedKey: string): Promise<KeyRecord | null> {
    const r = await this.client.send(
      new GetCommand({
        TableName: this.tableName,
        Key: { pk: pk(hashedKey), sk: "META" },
      }),
    );
    return r.Item ? itemToRecord(r.Item) : null;
  }
}

// Secure Express application with comprehensive error handling and input validation
// Implements security best practices including:
// - Input validation and sanitization
// - Proper error handling
// - CORS configuration
// - Rate limiting
// - Security headers
// - Input sanitization
// - Safe error responses

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Enable security headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameAncestors: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: "deny" },
  hidePoweredBy: true,
  httpStrictTransportSecurity: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again in 15 minutes' 
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Parse JSON bodies with size limit and safe parsing
app.use(express.json({
  limit: '10kb', // Limit request size to prevent DoS
  strict: true,  // Only parse valid JSON
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
}));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Validate input for user-related operations
const validateId = param('id')
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('ID must be a positive integer');

const validateUserIdQuery = query('id')
  .optional()
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('User ID must be a positive integer');

const validateUserCreate = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name can only contain letters, spaces, apostrophes, and hyphens'),

  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail({
      remove_dots: false,
      remove_extension: false,
      gmail_remove_dots: false,
      gmail_remove_subaddress: false,
    }),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Validate patch/update inputs
const validateUserUpdate = [
  body('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),

  body('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Safe error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }

  next();
};

// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log error details for debugging (but don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
  });

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};

// Users endpoint with validation - GET /users
app.get('/users', validateUserIdQuery, handleValidationErrors, (req, res, next) => {
  try {
    // Hardcoded user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if ID query parameter is provided
    if (req.query.id) {
      const filteredUsers = users.filter(user => user.id === parseInt(req.query.id));

      if (filteredUsers.length === 0) {
        return res.status(404).json({ error: 'User not found' });
      }

      return res.json(filteredUsers);
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Create user endpoint with validation - POST /users
app.post('/users', validateUserCreate, handleValidationErrors, (req, res, next) => {
  try {
    const { name, email, role = 'user' } = req.body;

    // In a real application, you would:
    // 1. Check if user already exists
    // 2. Hash passwords before storing
    // 3. Insert into database with parameterized queries

    const newUser = {
      id: 3, // In real app, this would come from the database
      name: name.trim(),
      email: email.trim().toLowerCase(),
      role: role,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// Update user endpoint with validation - PUT /users/:id
app.put('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const updates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Update database record

    res.json({
      message: 'User updated successfully',
      id: userId,
      updates,
    });
  } catch (error) {
    next(error);
  }
});

// Patch user endpoint with validation - PATCH /users/:id
app.patch('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const partialUpdates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Apply partial updates to database record

    res.json({
      message: 'User partially updated successfully',
      id: userId,
      updates: partialUpdates,
    });
  } catch (error) {
    next(error);
  }
