  if (params.concurrency) env.RUNNER_CONCURRENCY = String(params.concurrency);
  if (params.runId)      env.RUN_ID       = String(params.runId);

  // Generic env passthrough (test 12 / AgentDojo uses this)
  if (params.env && typeof params.env === "object") {
    for (const [k, v] of Object.entries(params.env)) {
      env[k] = String(v);
    }
  }

  // Shared env vars
  if (params.s3Bucket)  env.S3_BUCKET       = String(params.s3Bucket);
  if (params.s3Prefix)  env.S3_PREFIX       = String(params.s3Prefix);
  if (params.s3Region)  env.S3_REGION       = String(params.s3Region);
  if (params.awsRegion) env.AWS_REGION      = String(params.awsRegion);
  if (params.bedrockRegion) env.BEDROCK_REGION = String(params.bedrockRegion);

  const runId = env.TEST7_RUN_ID || env.TEST3_RUN_ID || new Date().toISOString().replace(/[:.]/g, "");

  state = {
    status: "running",
    runId,
    params,
    startedAt: new Date().toISOString(),
    finishedAt: null,
    exitCode: null,
    pid: null,
    logLines: [],
    progress: { ...INITIAL_PROGRESS },
  };

  const child = spawn(entrypoint, [], {
    env,
    stdio: ["ignore", "pipe", "pipe"],
  });

  state.pid = child.pid;
  currentProcess = child;

  child

# Security Improvements for app.js

## Comprehensive Analysis and Recommendations

After reviewing the `app.js` file, I've identified several areas where security can be improved, particularly around error handling and input validation. The current implementation is already quite good, but there are opportunities to enhance security and best practices.

---

## Critical Improvements Needed

### 1. **CORS Configuration Gap**
**Issue**: No CORS configuration present, which could expose the API to cross-origin attacks.

**Recommendation**: Add CORS configuration with explicit origin allowlists.

```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',')
    : ['https://your-trusted-domain.com'],
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
}));
```

### 2. **Input Validation Enhancements**
**Issue**: While validation exists, some cases lack comprehensive checks.

**Recommendations**:
- Add additional validation patterns for sensitive fields
- Implement stricter length limits to prevent DoS
- Add sanitization for potentially dangerous inputs

```javascript
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return input
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/javascript:/gi, '')
    .replace(/on\w+\s*=/gi, '');
};

const validateStrictInput = [
  body('name')
    .trim()
    .escape() // HTML escape
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),

  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),

  body('role')
    .optional()
    .trim()
    .escape()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];
```

### 3. **Error Handling - Stack Trace Exposure**
**Issue**: Potential stack trace exposure in non-production environments.

**Recommendation**: Enhance error handler to never expose stack traces in responses.

```javascript
const errorHandler = (err, req, res, next) => {
  // Log with full details internally
  console.error('Error occurred:', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.originalUrl,
    message: err.message,
    stack: err.stack,
    ip: req.ip || req.connection.remoteAddress,
    userAgent: req.headers['user-agent'],
  });

  // Determine error code
  const statusCode = err.status || err.statusCode || 500;

  // Generic error response - never expose internal details
  const response = {
    error: {
      message: process.env.NODE_ENV === 'production' 
        ? 'An error occurred processing your request'
        : err.message,
      code: err.code || 'INTERNAL_ERROR',
      timestamp: new Date().toISOString(),
      requestId: req.id || 'unknown',
    },
  };

  // Optional: Add error category in development
  if (process.env.NODE_ENV !== 'production') {
    response.error.category = err.name || 'Error';
  }

  res.status(statusCode).json(response);
};
```

### 4. **Additional Security Headers**
**Issue**: Missing some important security headers.

**Recommendation**: Add additional security headers.

```javascript
app.use((req, res, next) => {
  // Content type nosniff
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Permissions policy
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');

  // Cache control for sensitive endpoints
  if (req.path.includes('/users') || req.path.includes('/admin')) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
  }

  next();
});
```

### 5. **SQL Injection Prevention**
**Issue**: No database operations shown, but if database is added later.

**Recommendation**: Use parameterized queries and ORM with built-in protection.

```javascript
// Example using Sequelize or similar ORM
// Never use string concatenation for queries:
// WRONG: `SELECT * FROM users WHERE id = ${userId}`
// CORRECT: `SELECT * FROM users WHERE id = ?`, [userId]

// Or using prepared statements:
const query = 'SELECT * FROM users WHERE id = ?';
const values = [userId];
db.query(query, { replacements: values });
```

### 6. **Rate Limiting Granularity**
**Issue**: Global rate limiting applied to all endpoints.

**Recommendation**: Implement endpoint-specific rate limiting.

```javascript
// Global rate limiter for non-sensitive endpoints
app.use('/api/', rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: { error: 'Too many requests' }
}));

// Stricter rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts
  message: { error: 'Too many authentication attempts. Try again later.' }
});

app.post('/auth/login', authLimiter, (req, res) => {
  // Login logic
});
```

### 7. **CSRF Protection**
**Issue**: No CSRF protection for state-changing requests.

**Recommendation**: Add CSRF tokens for sensitive operations.

```javascript
const csurf = require('csurf');

// Apply to routes that modify data
app.post('/users', csurf(), validateUserCreate, handleValidationErrors, (req, res) => {
  // CSRF token validation handled automatically
  // Token available in req.csrfToken() for frontend
});
```

### 8. **Input Size Limits**
**Issue**: JSON body limit exists but could be more restrictive.

**Recommendation**: Set more restrictive and appropriate size limits.

```javascript
app.use(express.json({
  limit: '1mb', // More realistic for most APIs
  strict: true,
  type: 'application/json',
}));

// For file uploads or large payloads, use specific limits
app.post('/upload', {
  limit: '10mb',
  encodedFileLiteral: true,
});
```

### 9. **Date Validation**
**Issue**: No validation of date fields, which could lead to timestamp manipulation.

**Recommendation**: Add date validation patterns.

```javascript
const validateDateRange = (startDateField, endDateField) => {
  return [
    body(startDateField)
      .optional()
      .isISO8601()
      .withMessage(`${startDateField} must be a valid date`),
    body(endDateField)
      .optional()
      .isISO8601()
      .withMessage(`${endDateField} must be a valid date`),
  ];
};

// Usage
app.get('/reports', validateDateRange('startDate', 'endDate'), handleValidationErrors, (req, res) => {
  // Report logic
});
```

### 10. **Health Check Security**
**Issue**: Health check endpoint could expose sensitive information.

**Recommendation**: Limit health check response in production.

```javascript
app.get('/health', (req, res) => {
  try {
    const health = {
      status: 'ok',
      timestamp: new Date().toISOString(),
    };

    // Only include uptime in development
    if (process.env.NODE_ENV !== 'production') {
      health.uptime = process.uptime();
    }

    res.status(200).json(health);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

## Additional Security Recommendations

### 1. **Authentication and Authorization**
```javascript
// Add authentication middleware
const verifyToken = (req, res, next) => {
